package com.boostercloud.framework.provider.azure.infrastructure.functions;

import com.boostercloud.framework.provider.azure.infrastructure.types.Binding;
import com.boostercloud.framework.provider.azure.infrastructure.types.FunctionConfig;
import com.boostercloud.framework.provider.azure.infrastructure.types.FunctionDefinition;
import com.boostercloud.framework.types.BoosterConfig;
import java.util.List;

/**
 * Port of {@code functions/event-handler-function.ts}: the legacy definition of the events store change feed function
 * (pinned by tests; the Java worker definition is generated by {@code FunctionsCodeGenerator}).
 */
public final class EventHandlerFunction {

  private final BoosterConfig config;

  /**
   * @param config the configuration
   */
  public EventHandlerFunction(BoosterConfig config) {
    this.config = config;
  }

  /**
   * @return {@code eventHandler}: {@code cosmosDBTrigger} {@code rawEvent} on the events store with the lease container
   *     {@code leases} ({@code createLeaseContainerIfNotExists} is the string {@code 'true'}),
   *     {@code boosterEventDispatcher}
   */
  public FunctionDefinition getFunctionDefinition() {
    return new FunctionDefinition("eventHandler", new FunctionConfig(
        List.of(cosmosBinding(config)),
        config.functionRelativePath,
        LegacyFunctions.entryPoint(config.eventDispatcherHandler)));
  }

  static Binding cosmosBinding(BoosterConfig config) {
    return Binding.of(LegacyFunctions.ordered(
        "type", "cosmosDBTrigger",
        "name", "rawEvent",
        "direction", "in",
        "leaseContainerName", "leases",
        "connection", "COSMOSDB_CONNECTION_STRING",
        "databaseName", config.resourceNames().applicationStack(),
        "containerName", config.resourceNames().eventsStore(),
        "createLeaseContainerIfNotExists", "true"));
  }
}
